-- ═════════════════════════════════════════════════════════════════════
-- DATA BACKFILLS (hand-written). Each block is idempotent (it only fills
-- a value that is still unset) and touches only the columns added above.
-- Raw SQL never bumps the Prisma-managed "updatedAt" columns.
-- ═════════════════════════════════════════════════════════════════════

-- 1. Retenue à la source ships OFF (DECISIONS §4): every existing settings
-- row is switched off whatever its rate, until the accountant validates the
-- rule. The column default already did it; the explicit statement keeps
-- the intent if the default is ever changed. The threshold takes its
-- default (1 000 DT), the inactivity rule its defaults (off, 6 months).
UPDATE "CompanyBillingSettings"
SET "withholdingEnabled" = false
WHERE "withholdingEnabled" IS DISTINCT FROM false;

-- 2. Who released the batches already unlocked: inferred from their
-- installment. A paid installment unlocked its batch through settlement
-- (source payment); one closed at 0 by a quote edit (planRebalance) through
-- the edit (source installment_cancelled). The actor and the reason stay
-- null: they were never recorded. A batch unlocked under any other
-- installment status (none expected) keeps a null source.
UPDATE "QuoteStepBatch" AS b
SET "unlockSource" = CASE i."status"
    WHEN 'paid' THEN 'payment'::"BatchUnlockSource"
    ELSE 'installment_cancelled'::"BatchUnlockSource"
  END
FROM "QuoteInstallment" AS i
WHERE i."id" = b."installmentId"
  AND b."unlockedAt" IS NOT NULL
  AND b."unlockSource" IS NULL
  AND i."status" IN ('paid', 'cancelled');

-- 3. The declaration time of the treatment-fee transfers awaiting
-- confirmation: APPROXIMATED by the order's updatedAt (the last write,
-- normally the proof upload), the value the order page already showed.
-- New declarations stamp the real instant. Paid fees keep null (their
-- history is the audit log and treatmentFeePaidAt).
UPDATE "DentalOrder"
SET "treatmentFeeDeclaredAt" = "updatedAt"
WHERE "treatmentFeePaymentStatus" = 'awaiting_confirmation'
  AND "treatmentFeeDeclaredAt" IS NULL;

-- 4. The admins' bell rows of the transfers STILL awaiting confirmation
-- get their subject key, so those transfers show "Nouveau" / "Consulté"
-- per admin (and count in the badge while unread) from day one. Same
-- formats as src/notifications/notification-subject.ts:
--   installment:<paymentId>
--   treatment_fee:<orderId>:<treatmentFeeDeclaredAt epoch ms>
-- (the latter uses the value block 3 just wrote). Rows of transfers already
-- processed keep a null key and are ignored by the badge.
UPDATE "Notification" AS n
SET "subjectKey" = 'installment:' || p."id"
FROM "Payment" AS p
WHERE n."type" = 'payment_declared'
  AND n."subjectKey" IS NULL
  AND n."metadata" ->> 'paymentId' = p."id"
  AND p."status" = 'awaiting_confirmation';

UPDATE "Notification" AS n
SET "subjectKey" = 'treatment_fee:' || o."id" || ':'
  || floor(extract(epoch FROM o."treatmentFeeDeclaredAt") * 1000)::bigint::text
FROM "DentalOrder" AS o
WHERE n."type" = 'treatment_fee_declared'
  AND n."subjectKey" IS NULL
  AND n."metadata" ->> 'orderId' = o."id"
  AND o."treatmentFeePaymentStatus" = 'awaiting_confirmation'
  AND o."treatmentFeeDeclaredAt" IS NOT NULL;

-- 5. Invoices billed to their practitioner: the rule the stored-invoice
-- PDF applied live (invoice-pdf.service.ts, "billsPractitioner": linked to
-- a doctor AND clientName = that doctor's fullName, both trimmed) is frozen
-- into clientIsPractitioner, evaluated on the names as they stand at
-- migration time.
-- 6. The clinic those invoices print ("Docteur : X" + clinic), copied from
-- the CURRENT DentistProfile, as the PDF read it live. Only the
-- practitioner invoices: the others never printed a clinic.
-- "Trimmed" is JavaScript's String.prototype.trim(), which the PDF uses, not
-- a bare btrim() (spaces only): ASCII TAB LF VT FF CR SPACE, plus, on a
-- UTF8 database (chr() of a non-ASCII code point is refused elsewhere),
-- NBSP, U+1680, U+2000-U+200A, U+2028, U+2029, U+202F, U+205F, U+3000 and
-- U+FEFF. Built at run time in PL/pgSQL so a non-UTF8 database never
-- evaluates the non-ASCII chr() calls.
DO $backfill$
DECLARE
  ws text := E' \t\n\r\f' || chr(11);
  code int;
BEGIN
  IF current_setting('server_encoding') = 'UTF8' THEN
    FOREACH code IN ARRAY ARRAY[160, 5760, 8232, 8233, 8239, 8287, 12288, 65279] LOOP
      ws := ws || chr(code);
    END LOOP;
    FOR code IN 8192..8202 LOOP
      ws := ws || chr(code);
    END LOOP;
  END IF;

  UPDATE "Invoice" AS inv
  SET "clientIsPractitioner" = true
  FROM "User" AS u
  WHERE u."id" = inv."doctorId"
    AND inv."clientIsPractitioner" = false
    AND btrim(u."fullName", ws) <> ''
    AND btrim(inv."clientName", ws) = btrim(u."fullName", ws);

  UPDATE "Invoice" AS inv
  SET "clientClinicName" = dp."clinicName"
  FROM "DentistProfile" AS dp
  WHERE dp."userId" = inv."doctorId"
    AND inv."clientIsPractitioner" = true
    AND inv."clientClinicName" IS NULL
    AND btrim(dp."clinicName", ws) <> '';
END
$backfill$;

-- 7. Mark blocks 5 and 6 as BACKFILLED (not truly historical): one
-- InvoiceAuditLog row per invoice they changed, action
-- 'client_snapshot_backfilled', system actor (actorId null), the values
-- written as { field: { from, to } } like every invoice audit row.
INSERT INTO "InvoiceAuditLog" ("id", "invoiceId", "actorId", "actorName", "action", "changes", "createdAt")
SELECT
  gen_random_uuid()::text,
  inv."id",
  NULL,
  'Reprise des données (migration 2026-11-27)',
  'client_snapshot_backfilled',
  jsonb_build_object(
    'clientIsPractitioner', jsonb_build_object('from', false, 'to', true)
  ) || CASE
    WHEN inv."clientClinicName" IS NOT NULL THEN jsonb_build_object(
      'clientClinicName', jsonb_build_object('from', NULL, 'to', inv."clientClinicName")
    )
    ELSE '{}'::jsonb
  END,
  CURRENT_TIMESTAMP
FROM "Invoice" AS inv
WHERE inv."clientIsPractitioner" = true
  AND NOT EXISTS (
    SELECT 1 FROM "InvoiceAuditLog" AS log
    WHERE log."invoiceId" = inv."id"
      AND log."action" = 'client_snapshot_backfilled'
  );

-- Not backfilled on purpose (null = "before the rule"): the withholding
-- threshold snapshots (Payment, DentalOrder, Invoice), quoteRemainingAfter,
-- the review / cancel / rejection stamps, the declaration keys,
-- OrderAuditLog.paymentId, User.approvedAt (no approval history exists:
-- the inactivity anchor falls back to createdAt), User.inactiveSince and
